using System.ComponentModel.DataAnnotations;

namespace FleetManagerApi.DTOs
{
    // Deliberately narrow: only the fields that make sense to set at creation time.
    // CreatedAt is excluded — it will be set to the current UTC time on the server.
    // CustomerID is excluded — it will be generated by the database.
    // FullName, Email, PhoneNumber, and DriverLicenseNo are required.
    // Email is validated to be a valid email address format.

    public class CreateCustomerDto
    {
        [Required, StringLength(100)]
        public string FullName { get; set; } = string.Empty;

        [Required, EmailAddress, StringLength(100)]
        public string Email { get; set; } = string.Empty;

        [Required, StringLength(20)]
        public string PhoneNumber { get; set; } = string.Empty;

        [Required, StringLength(50)]
        public string DriverLicenseNo { get; set; } = string.Empty;
    }
    // Deliberately narrow: only the fields that make sense to edit after creation.
    // CustomerID is excluded — it should never be changed.
    // CreatedAt is excluded — it should never be changed.
    // FullName, Email, PhoneNumber, and DriverLicenseNo are required.
    // Email is validated to be a valid email address format.
    // This DTO is used for updating an existing customer.
    public class UpdateCustomerDto
    {
        [Required, StringLength(100)]
        public string FullName { get; set; } = string.Empty;

        [Required, EmailAddress, StringLength(100)]
        public string Email { get; set; } = string.Empty;

        [Required, StringLength(20)]
        public string PhoneNumber { get; set; } = string.Empty;

        [Required, StringLength(50)]
        public string DriverLicenseNo { get; set; } = string.Empty;
    }
}
